'use client'

import './scribble-highlight.css'
import { type DrawInViewOptions, drawInView } from '@kida-ui/motion'
import type { HTMLAttributes, ReactNode } from 'react'
import { forwardRef, useRef } from 'react'
import { composeRefs } from './compose-refs.js'
import { useIsomorphicLayoutEffect } from './use-isomorphic-layout-effect.js'

export interface ScribbleHighlightProps
  extends DrawInViewOptions,
    Omit<HTMLAttributes<HTMLSpanElement>, 'children'> {
  children?: ReactNode
  /** Shape drawn around the content. @default 'underline' */
  variant?: 'underline' | 'circle'
}

const paths = {
  underline: 'M2 12.5 C18 8.5 34 15.5 50 11 C66 6.5 82 14 98 9.5',
  circle: 'M6 10 C16 1 78 0 94 8 C104 15 88 20 50 19 C14 19 -3 15 6 10',
} as const

export const ScribbleHighlight = forwardRef<HTMLSpanElement, ScribbleHighlightProps>(
  function ScribbleHighlight(
    { children, variant = 'underline', once, amount, ...props },
    forwardedRef,
  ) {
    const ref = useRef<HTMLSpanElement>(null)
    const optionsRef = useRef({ once, amount })

    useIsomorphicLayoutEffect(() => {
      const element = ref.current
      if (!element) return
      return drawInView(element, optionsRef.current)
    }, [])

    return (
      <span
        {...props}
        ref={composeRefs(ref, forwardedRef)}
        data-kida-scribble=""
        data-variant={variant}
        data-state="idle"
      >
        <span data-kida-scribble-content="">{children}</span>
        <svg aria-hidden="true" viewBox="0 0 100 20" preserveAspectRatio="none">
          <path d={paths[variant]} pathLength="1" />
        </svg>
      </span>
    )
  },
)

import type { Ref } from 'react'

/** Feed one node to several refs — ours for measuring, Zag's for animation detection. */
export function composeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === 'function') ref(node)
      else if (ref) (ref as { current: T | null }).current = node
    }
  }
}

@import './tokens.css';

[data-kida-scribble] {
  --kida-scribble-color: #e94f86;
  --kida-scribble-width: 0.14em;
  --kida-scribble-duration: 650ms;

  position: relative;
  display: inline-block;
  isolation: isolate;
}

[data-kida-scribble-content] {
  position: relative;
  z-index: 1;
}

[data-kida-scribble] svg {
  position: absolute;
  z-index: 0;
  left: -4%;
  width: 108%;
  overflow: visible;
  pointer-events: none;
}

[data-kida-scribble][data-variant="underline"] svg {
  top: 78%;
  height: 0.55em;
}

[data-kida-scribble][data-variant="circle"] svg {
  inset: -12% -7%;
  width: 114%;
  height: 124%;
}

[data-kida-scribble] path {
  fill: none;
  stroke: var(--kida-scribble-color);
  stroke-width: var(--kida-scribble-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

[data-kida-scribble][data-state="active"] path,
[data-kida-scribble][data-state="settled"] path {
  animation: kida-scribble-draw var(--kida-scribble-duration) var(--kida-ease-out) forwards;
}

@keyframes kida-scribble-draw {
  to {
    stroke-dashoffset: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-kida-scribble] path {
    animation: none;
    stroke-dashoffset: 0;
  }
}

/*
 * Kida UI — motion tokens.
 * Plain CSS custom properties (ADR D7). No preprocessor, no Tailwind, no build step.
 */

:root {
  /* Durations */
  --kida-duration-xs: 100ms;
  --kida-duration-sm: 150ms;
  --kida-duration-md: 300ms;
  --kida-duration-lg: 500ms;
  --kida-duration-xl: 800ms;

  /* Easings */
  --kida-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --kida-ease-in: cubic-bezier(0.7, 0, 0.84, 0);
  --kida-ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --kida-ease-spring: linear(0, 0.5, 0.9, 1.02, 1);

  /* Travel distances used by the enter/exit keyframes */
  --kida-distance-sm: 4px;
  --kida-distance-md: 8px;
  --kida-distance-lg: 16px;

  /* Stagger step between siblings */
  --kida-stagger: 60ms;
}

/*
 * The single reduced-motion guard for every CSS-driven animation in the library.
 * Durations collapse to ~0 instead of being disabled, so `animationend` still fires
 * and presence-based unmounts (ADR D5) never hang.
 */
@media (prefers-reduced-motion: reduce) {
  :root {
    --kida-duration-xs: 1ms;
    --kida-duration-sm: 1ms;
    --kida-duration-md: 1ms;
    --kida-duration-lg: 1ms;
    --kida-duration-xl: 1ms;
    --kida-distance-sm: 0px;
    --kida-distance-md: 0px;
    --kida-distance-lg: 0px;
    --kida-stagger: 0ms;
  }
}
